<?php
 require_once(__DIR__ . '/../../init.php'); class med_card_exportPatients { const LOG = 'medCardExportPatients'; const SLEEP_TIMEOUT = 1; const GC_COLLECT_EVERY_CYCLES = 1000; private $db; private $log; public function toViaduct ($jsonPath = null) { $this->log = $log = new \Log(self::LOG); $log->begin("Старт экспорта пациентов в Viaduct"); if (empty($jsonPath)) { $log->error('Не указан путь для сохранения JSON-файлов'); } $jsonPath = realpath($jsonPath); $log->info("Путь для сохранения JSON-файлов \"$jsonPath\""); $db = $this->db ? : $this->db = connectDb(); $lock = selectSqlValue($db, "select pg_try_advisory_lock('medpatientbroker'::regclass::bigint)"); if ($lock) { $log->info("Получена блокировка сеанса"); try { $cycles = 0; while (true) { if ($cycles >= self::GC_COLLECT_EVERY_CYCLES) { $before = memory_get_usage(); $log->info("Очистка памяти..."); gc_collect_cycles(); $cycles = 0; $after = memory_get_usage(); $log->time("ОК [$before => $after]"); } $mpc = selectSqlValue($db, "select MedPatientCode from MedPatientBroker order by CreateTime limit 1"); if (empty($mpc)) { sleep(self::SLEEP_TIMEOUT); } else { $log->info("Обработка пациента [$mpc]..."); try { ++$cycles; executeSql($db, "delete from MedPatientBroker where MedPatientCode = ?", [$mpc]); $json = selectSqlValue($db, "select FN_MedPatientInfo(?)", [$mpc]); if (empty($json)) { $log->warning('Отсутствует информация по пациенту'); continue; } $ftmp = "{$jsonPath}/patient_{$mpc}.tmp"; $fjson = "{$jsonPath}/patient_{$mpc}.json"; if (file_put_contents($ftmp, $json) === false) { $log->error("Ошибка записи в файл \"$ftmp\""); continue; } if (rename($ftmp, $fjson) === false) { $log->error("Ошибка переименовывания файла \"$ftmp\" в \"$fjson\""); continue; } $log->time("ОК"); } catch (Throwable $e) { $log->error("Возникло исключение:")->text($e->getMessage() . "\n" . $e->getTraceAsString()); } } } } finally { selectSql($db, "select pg_advisory_unlock('medpatientbroker'::regclass::bigint)"); $log->info("Снята блокировка сеанса"); } } else { $log->error("В блокировке сеанса отказано, функция уже запущена в другом процессе"); } $log->end("Завершение экспорта пациентов в Viaduct"); } public function getPatientInfo($params) { $this->log = $log = new \Log(self::LOG); $settings = readJsonSettings('settings_med'); if (!isset($settings['configName'])) { throw new Exception("Отсутствует настройка конфигурации 'configName' в файле cfg/settings_med.json!"); } $db = $this->db ? : $this->db = connectDb($settings['configName']); $log->begin('Получение информации о пациенте'); $json = null; $personalNumber = isEmptyProperty($params, 'personalNumber', ''); if (empty($personalNumber)) { $log->error('Пустой персональный номер в запросе'); throw new Exception("Пустой персональный номер в запросе"); } else { $manCode = selectSqlValue($db, "select manCode from ManPassport where personalNumber = ? limit 1", [$personalNumber]); if (empty($manCode)) { $log->error("manCode для personalNumber = $personalNumber не найден"); throw new Exception("manCode для personalNumber = $personalNumber не найден"); } else { $medPatientCode = selectSqlValue($db, "select medPatientCode from MedPatient where manCode = ? limit 1", [$manCode]); } if (empty($medPatientCode)) { $log->error("medPatientCode для manCode = $manCode не найден"); throw new Exception("medPatientCode для manCode = $manCode не найден"); } else { $json = selectSqlValue($db, "select FN_MedPatientInfo_PG(?)", [$medPatientCode]); } $log->end('Получение информации о пациенте закончено'); } return safe_json_decode($json); } } handleJsonRpc('med_card_exportPatients'); 